const args = process.argv.slice(2)
const only = args.includes('--only') ? new Set(args[args.indexOf('--only') + 1].split(',')) : undefined
const noE2e = args.includes('--no-e2e')
const summary = out => (out.match(/^\s*Tests\s{2,}[^\n]+/gm) ?? []).pop()?.trim() ?? '(无 vitest 汇总行)'
const firstFail = out => (out.match(/(?:×|FAIL)\s+[^\n]+/) ?? [''])[0].trim().slice(0, 160)

const run = (cmd) => spawnSync(cmd[0], cmd.slice(1), { cwd: ROOT, encoding: 'utf8', env: { ...process.env, FORCE_COLOR: '0' } })
fs.mkdirSync(path.join(ROOT, '.tmp/mutate'), { recursive: true })
// 保险：改文件前把原文写进 JOURNAL；进程被硬杀（finally 来不及跑）时，下次启动先从这里还原
const JOURNAL = path.join(ROOT, '.tmp/mutate/RESTORE-ME.json')
if (fs.existsSync(JOURNAL)) {
  const j = JSON.parse(fs.readFileSync(JOURNAL, 'utf8'))
  for (const [f, t] of Object.entries(j)) fs.writeFileSync(f, t)
  fs.rmSync(JOURNAL)
  console.log(`上次没还原完：已从 ${JOURNAL} 还原 ${Object.keys(j).length} 个文件`)
  run(['pnpm', 'build'])
}
const logFile = path.join(ROOT, '.tmp/mutate', `${new Date().toISOString().replace(/[:.]/g, '-')}.log`)
const rows = []
let bad = 0
for (const m of MUTATIONS) {
  if (only && !only.has(m.id)) continue
  if (noE2e && (m.cmd === e2e || m.cmd === e2e3)) continue
  const edits = m.edits ?? [{ file: m.file, find: m.find, replace: m.replace }]
  const originals = new Map(edits.map(e => [e.file, fs.readFileSync(e.file, 'utf8')]))
  const miss = edits.find(e => originals.get(e.file).split(e.find).length - 1 !== 1)
  if (miss) { rows.push([m.id, m.what, `改动点在 ${path.basename(miss.file)} 不是恰好出现 1 次`, '✗ 无法注入']); bad++; continue }
  let out = ''; let code = -1
  try {
    const next = new Map(originals)
    for (const e of edits) next.set(e.file, next.get(e.file).replace(e.find, e.replace))
    fs.writeFileSync(JOURNAL, JSON.stringify(Object.fromEntries(originals)))
    for (const [f, t] of next) fs.writeFileSync(f, t)
    if (m.build) { const b = run(['pnpm', 'build']); if (b.status !== 0) throw new Error('build failed: ' + b.stdout + b.stderr) }
    const r = run(m.cmd); out = r.stdout + r.stderr; code = r.status ?? -1
  } finally {
    for (const [f, t] of originals) fs.writeFileSync(f, t)
    fs.rmSync(JOURNAL, { force: true })
    if (m.build) run(['pnpm', 'build'])
  }
  const red = code !== 0
  const ok = m.expectGreen ? !red : red
  if (!ok) bad++
  rows.push([m.id, m.what, `${summary(out)}${red ? ' ｜ ' + firstFail(out) : ''}`, m.expectGreen ? (red ? '✗ 意外变红' : '✓ 仍绿（符合预期）') : (red ? '✓ 变红' : '✗ 仍然绿')])
  fs.appendFileSync(logFile, `\n===== ${m.id}：${m.what}\n$ ${m.cmd.join(' ')}\nexit=${code}\n${out}\n`)
  console.log(`${ok ? '✓' : '✗'} ${m.id}  ${m.what}  →  ${summary(out)}`)
}
// 还原后整体再跑一遍，确认绿
const back = run(unit([]))
console.log(`\n还原后单测：${summary(back.stdout + back.stderr)}（exit=${back.status}）`)
console.log(`明细日志：${logFile}`)
const table = '\n| 编号 | 去掉了什么 | 读数 | 结果 |\n|---|---|---|---|\n' + rows.map(r => `| ${r.join(' | ')} |`).join('\n')
console.log(table)
fs.appendFileSync(logFile, `\n===== 汇总\n还原后单测：${summary(back.stdout + back.stderr)}（exit=${back.status}）\n${table}\n`)
process.exit(bad || back.status ? 1 : 0)
